SELECT a.*, c.name AS category_name, f.original_name AS cover_file_name,
FROM blog_article a LEFT JOIN blog_category c ON c.id = a.category_id LEFT JOIN blog_file f ON f.id = a.cover_file_id
WHERE a.id = #{id}

SELECT 
FROM blog_article a

WHERE a.status = #{publishedStatus}

    AND (a.title LIKE CONCAT('%', #{searchKeyword}, '%')
         OR a.summary LIKE CONCAT('%', #{searchKeyword}, '%'))


    AND a.category_id = #{categoryId}


    AND EXISTS (
        SELECT 1
        FROM blog_article_tag filter_tag
        INNER JOIN blog_tag selected_tag ON selected_tag.id = filter_tag.tag_id
        WHERE filter_tag.article_id = a.id AND filter_tag.tag_id = #{tagId}
    )

ORDER BY a.published_at DESC, a.id DESC

SELECT article_tag.article_id AS id, FROM blog_article_tag article_tag INNER JOIN blog_tag t ON t.id = article_tag.tag_id WHERE article_tag.article_id IN
#{articleId}
ORDER BY article_tag.article_id, t.id

